CREATE TABLE usage_dedup(day TEXT NOT NULL,digest TEXT NOT NULL,marker TEXT,expires INTEGER NOT NULL,PRIMARY KEY(day,digest)) WITHOUT ROWID;
CREATE INDEX usage_dedup_expiry ON usage_dedup(expires);
CREATE TABLE usage_quota(day TEXT PRIMARY KEY,accepted INTEGER NOT NULL) WITHOUT ROWID;
CREATE TABLE usage_days(day TEXT NOT NULL,app TEXT NOT NULL,devices INTEGER NOT NULL,PRIMARY KEY(day,app)) WITHOUT ROWID;
CREATE TABLE usage_events(day TEXT NOT NULL,app TEXT NOT NULL,name TEXT NOT NULL,total INTEGER NOT NULL,devices INTEGER NOT NULL,PRIMARY KEY(day,app,name)) WITHOUT ROWID;
CREATE TABLE usage_states(day TEXT NOT NULL,app TEXT NOT NULL,name TEXT NOT NULL,value TEXT NOT NULL,devices INTEGER NOT NULL,PRIMARY KEY(day,app,name,value)) WITHOUT ROWID;
